121:     public boolean request() {
122:         SelectedSubtitleSource source = mHost.getSelectedSource();
123: 
124:         if (source == null) {
125:             mRequests.cancel(); // subtitles off (or not bound yet): no attempt may outlive it
126: 
127:             return false;
128:         }
129: 
130:         String locator = locatorOf(source);
131: 
132:         if (mHost.getTimelineOfCurrentSource() != null) {
133:             mInstalledLocator = locator;
134: 
135:             return false; // this source identity already has its decoded timeline
136:         }
137: 
138:         Format format = mHost.getSelectedFormat();
139:         SubtitleSnapshotFetcher.PayloadFactory factory = mHost.createPayloadFactory();
140: 
141:         if (format == null || factory == null) {
142:             return false; // the player surface cannot describe the payload yet; the next event retries
143:         }
144: 
145:         // The same payload in another generation (manifest rebuilt, track re-resolved): re-attribute
146:         // the decoded timeline instead of downloading and decoding the same text again.
147:         SubtitleTimeline installed = mHost.getInstalledTimeline();
148: 
149:         if (installed != null && locator != null && locator.equals(mInstalledLocator)) {
150:             mHost.installTimeline(installed);
151:             mListener.onAttemptSettled(STATUS_REUSED, true, true);
152: 
153:             return false;
154:         }
155: 
156:         SubtitleTimelineScheduler.Request request = mRequests.begin(mMediaGeneration,
157:                 mHost.getCurrentSourceKey(), locator);
158: 
159:         if (request == null) {
160:             return false; // the same identity is already in flight: reuse it
161:         }
162: 
163:         mWorker.execute(() -> run(request, source, format, factory));
164: 
165:         return true;

